function scheduleEditorDraft(){clearTimeout(draftTimer);if(!db||!$('#editor-dialog').open)return;draftTimer=setTimeout(async()=>{if(!db||busy||saveError||!$('#editor-dialog').open||currentEditor()===editorSnapshot)return;db.draftEditor={id:editing,kind:editKind,domain:$('#record-domain').value,title:$('#record-title').value,body:$('#record-body').value,document:rich.document(),appearance:editorAppearance,studio:studio.state(),sourceText:editingSourceText,tags:$('#record-tags').value,status:$('#record-status').value,url:$('#record-url').value,username:$('#account-user').value,password:$('#account-password').value,loginMethod:$('#account-login').value,balance:$('#account-balance').value,images:[...editImages],media:[...editMedia]};try{await save();$('#studio-draft-state').textContent='草稿已同步到云端';}catch{$('#studio-draft-state').textContent='草稿同步失败，请保留页面';}},8000);}
