async function lock(){if(!db||busy)return;if(saveError){toast('有记录尚未保存。请先导出加密备份，再锁定。');return;}busy=true;try{await queue;if($('#editor-dialog').open&&currentEditor()!==editorSnapshot){db.draftEditor={id:editing,kind:editKind,domain:$('#record-domain').value,title:$('#record-title').value,body:$('#record-body').value,document:rich.document(),appearance:editorAppearance,studio:studio.state(),sourceText:editingSourceText,tags:$('#record-tags').value,status:$('#record-status').value,url:$('#record-url').value,username:$('#account-user').value,password:$('#account-password').value,loginMethod:$('#account-login').value,balance:$('#account-balance').value,images:[...editImages],media:[...editMedia]};}db.quickDraft=$('#quick-text').value;db.captureDraft=$('#capture-text').value;db.captureFields=Object.fromEntries(Object.entries(captureFields).map(([key,id])=>[key,$('#'+id).value]));await save();await api('/api/logout',{method:'POST'});setMenuOpen(false);syncQuickNavigation('');$$('dialog[open]').forEach(d=>d.close());industry.clear();aiIndustry.clear();shanghai.clear();quant.clear();daily.clear();db=null;cryptoKey=null;salt=null;envelope=null;editImages=[];editMedia=[];editing=null;selected=null;$('#records').innerHTML='';revokeMedia();$('#detail-body').innerHTML='';$('#overview-top').innerHTML='';$('#side-tags').innerHTML='';$('#nav').innerHTML='';$('#editor-form').reset();clearTimeout(draftTimer);rich.clear();studio?.clear();editingSourceText='';capturePrediction=null;captureOverrides.clear();for(const id of Object.values(captureFields))$('#'+id).value='';$('#capture-password').value='';$('#capture-user').value='';$('#capture-login').value='';$('#capture-balance').value='';$('#attachments').innerHTML='';$('#quick-text').value='';$('#capture-text').value='';$('#search').value='';$('#toast').classList.remove('visible');$('#app').hidden=true;$('#mobile-add').hidden=true;$('#gate').hidden=false;setupGate();}catch{toast('锁定前保存失败，请先备份。');}finally{busy=false;}}
